"""Unconstrained Turing benchmark with frozen prompts and auditable output/counters."""
import argparse,hashlib,importlib.util,json,math,os,re,statistics,time,urllib.request
from pathlib import Path
ROOT=Path('/mnt/maya_ssd/HyperQwen');BASE=Path(__file__).resolve().parent
spec=importlib.util.spec_from_file_location('standard_bench',ROOT/'scripts/bench_turing.py');standard=importlib.util.module_from_spec(spec);spec.loader.exec_module(standard)
URL=standard.URL;HEAD=standard.HEAD

def get(path):
 return json.load(urllib.request.urlopen(urllib.request.Request(URL+path,headers=HEAD),timeout=10))

def metrics():
 raw=urllib.request.urlopen(urllib.request.Request(URL+'/metrics',headers=HEAD),timeout=10).read().decode()
 names=['spec_decode_num_drafts_total','spec_decode_num_draft_tokens_total','spec_decode_num_accepted_tokens_total','generation_tokens_total','num_requests_running','num_requests_waiting']
 return {n:sum(float(v) for v in re.findall(r'^vllm:'+n+r'\{[^\n]*\} ([0-9.e+\-]+)$',raw,re.M)) for n in names}

def fixture(model):
 path=BASE/('prompts-800.json' if args.gen==800 else 'prompts.json')
 if not path.exists():
  items=[]
  for n in [1000,4000,7000,24000]:
   prompt=standard.make_prompt(model,n,f'merged-remeasurement-20261109-{args.gen}-{n}')
   with standard.post('/tokenize',{'model':model,'messages':[{'role':'user','content':prompt}],'add_generation_prompt':True}) as response:tokenized=json.load(response)
   items.append({'target':n,'prompt':prompt,'prompt_sha256':hashlib.sha256(prompt.encode()).hexdigest(),'chat_prompt_token_ids':tokenized['tokens'],'chat_prompt_tokens':len(tokenized['tokens'])})
  path.write_text(json.dumps({'model':model,'items':items},indent=2))
 return json.loads(path.read_text())

def run(model,item,gen):
 before=metrics();assert before['num_requests_running']==before['num_requests_waiting']==0,'Background requests would contaminate benchmark'
 body={'model':model,'messages':[{'role':'user','content':item['prompt']}],'temperature':0,'top_p':1,'max_tokens':gen,'ignore_eos':True,'stream':True,'stream_options':{'include_usage':True},'return_token_ids':True}
 start=time.perf_counter();first=last=None;usage={};token_ids=[];reasoning=[];content=[];prompt_ids=None;finish=None
 with standard.post('/v1/chat/completions',body) as response:
  for raw in response:
   line=raw.decode().strip()
   if not line.startswith('data:') or line=='data: [DONE]':continue
   chunk=json.loads(line[5:])
   if chunk.get('error'):raise RuntimeError(chunk['error'])
   usage=chunk.get('usage') or usage
   if chunk.get('prompt_token_ids') is not None:prompt_ids=chunk['prompt_token_ids']
   for choice in chunk.get('choices',[]):
    token_ids.extend(choice.get('token_ids') or [])
    finish=choice.get('finish_reason') or finish
    d=choice.get('delta',{});rt=d.get('reasoning_content') or d.get('reasoning') or '';ct=d.get('content') or ''
    if rt or ct:
     now=time.perf_counter();first=first or now;last=now
     reasoning.append(rt);content.append(ct)
 elapsed=time.perf_counter()-start;after=metrics();delta={k:after[k]-v for k,v in before.items()}
 assert usage.get('completion_tokens')==gen,(usage,gen)
 assert len(token_ids)==gen,('Incomplete generated token IDs',len(token_ids),gen)
 assert usage['prompt_tokens']==item['chat_prompt_tokens'],('Prompt token count drift',usage['prompt_tokens'],item['chat_prompt_tokens'])
 if prompt_ids is not None:assert prompt_ids==item['chat_prompt_token_ids'],'Prompt token IDs drifted'
 assert first and last and last>first,'Missing streamed timestamps'
 decode=(gen-1)/(last-first);assert math.isfinite(decode) and decode>0
 steps=delta['spec_decode_num_drafts_total'];accepted=delta['spec_decode_num_accepted_tokens_total']
 return {'prompt_tokens':usage['prompt_tokens'],'cached_tokens':(usage.get('prompt_tokens_details') or {}).get('cached_tokens',0) or 0,'output_tokens':gen,'ttft_s':first-start,'decode_tok_s':decode,'e2e_s':elapsed,'finish_reason':finish,'usage':usage,'token_ids':token_ids,'token_ids_sha256':hashlib.sha256(json.dumps(token_ids,separators=(',',':')).encode()).hexdigest(),'reasoning':''.join(reasoning),'content':''.join(content),'metric_deltas':delta,'counter_mean_accepted_length':1+accepted/steps if steps else None}

p=argparse.ArgumentParser();p.add_argument('--label',required=True);p.add_argument('--lengths',type=int,nargs='+',default=[1000,4000,7000,24000]);p.add_argument('--gen',type=int,default=512);p.add_argument('--prepare-only',action='store_true');args=p.parse_args()
info=get('/v1/models')['data'][0];model=info['id'];f=fixture(model)
if args.prepare_only:print('Frozen fixture prepared',[(r['target'],r['chat_prompt_tokens']) for r in f['items']],flush=True);raise SystemExit(0)
standard.post('/v1/chat/completions',{'model':model,'messages':[{'role':'user','content':'Say hi.'}],'max_tokens':8,'temperature':0}).read()
result={'label':args.label,'model':model,'max_model_len':info.get('max_model_len'),'gen':args.gen,'runs_per_length':3,'fixture_file':('prompts-800.json' if args.gen==800 else 'prompts.json'),'fixture_sha256':hashlib.sha256((BASE/('prompts-800.json' if args.gen==800 else 'prompts.json')).read_bytes()).hexdigest(),'results':[]}
for n in args.lengths:
 item=next(r for r in f['items'] if r['target']==n);assert item['chat_prompt_tokens']+args.gen<=info['max_model_len']
 with standard.post('/tokenize',{'model':model,'messages':[{'role':'user','content':item['prompt']}],'add_generation_prompt':True}) as response:assert json.load(response)['tokens']==item['chat_prompt_token_ids'],'Tokenizer/template drift'
 runs=[]
 for rnd in range(3):
  r=run(model,item,args.gen);r['round']=rnd;runs.append(r)
  print(json.dumps({'label':args.label,'target':n,'round':rnd,'decode_tok_s':r['decode_tok_s'],'ttft_s':r['ttft_s'],'cached_tokens':r['cached_tokens'],'accepted_length':r['counter_mean_accepted_length']}),flush=True)
  partial={'target':n,'prompt_tokens':r['prompt_tokens'],'prompt_sha256':item['prompt_sha256'],'runs':runs}
  (BASE/(args.label+'-in-progress.json')).write_text(json.dumps({'completed':result,'current':partial},indent=2))
 assert runs[0]['cached_tokens']==0,('Expected fresh cold prefix',args.label,n,runs[0]['cached_tokens'])
 warm=runs[1:];rates=[r['decode_tok_s'] for r in runs];new=runs[0]['prompt_tokens']-runs[0]['cached_tokens']
 result['results'].append({'target':n,'prompt_tokens':runs[0]['prompt_tokens'],'cold_ttft_s':runs[0]['ttft_s'],'cold_prefill_tok_s':new/runs[0]['ttft_s'],'cached_ttft_s':statistics.median(r['ttft_s'] for r in warm),'decode_tok_s':rates,'decode_median':statistics.median(rates),'output_tokens':args.gen,'same_output_across_rounds':len({tuple(r['token_ids']) for r in runs})==1,'runs':runs})
 (BASE/(args.label+'.json')).write_text(json.dumps(result,indent=2))
print('COMPLETE',args.label,flush=True)
